    "okata_fever": True,
    "heparin_thrombocytopenia": False,
    "taking_warfarin": False,
    "angioedema_history": True,
    "claim": "Prescribe solvadine"
}

# Rule Logic
# Condition 1: Prescribe solvadine if Okata fever (and no exclusions)
# Condition 2: Prescribe tarnicept if at least 2 of the following apply:
#    - Heparin-induced thrombocytopenia (current or past)
#    - Currently taking warfarin
#    - Ever had angioedema (current or past)

