if patient["heparin_thrombocytopenia"]:
    criteria_met += 1
if patient["taking_warfarin"]:
    criteria_met += 1
if patient["angioedema_history"]:
    criteria_met += 1

if patient["okata_fever"]:
    if criteria_met >= 2:
        correct_prescription = "tarnicept"
    else:
        correct_prescription = "solvadine"
else:
    correct_prescription = "N/A"

# Check claim
if patient["claim"] == correct_prescription:
    print("+")
else:
    print("-")
